132	func convertUserTagsSettingToStore(setting *v1pb.UserSetting_TagsSetting) *storepb.TagsUserSetting {
133		if setting == nil {
134			return &storepb.TagsUserSetting{Tags: map[string]*storepb.UserTagMetadata{}}
135		}
